package dev.chyken.assembl_ar;

import android.content.*;import android.net.Uri;import android.os.*;import android.graphics.*;import android.text.*;import android.view.*;import android.widget.*;
import androidx.appcompat.app.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
import dev.chyken.assembl_ar.learning.*;import dev.chyken.assembl_ar.ui.*;

/** Offline block practice + editable sketch export. Simulation never controls a connected robot. */
public final class ProgrammingPracticeActivity extends AppCompatActivity {
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();
    private List<NeobotProgram.Block> blocks;private LinearLayout rows;private EditText code;private TextView status;private SimulationView simulation;private ProgramSimulator run;
    private AssemblyVoiceGuide voice;private boolean editing,settingCode,customCode;private String pendingExport;private long tickTime;
    private final Runnable tick=new Runnable(){public void run(){if(run==null)return;long now=SystemClock.elapsedRealtime();run.advance((int)Math.min(100,Math.max(0,now-tickTime)));tickTime=now;simulation.invalidate();status.setText(run.finished()?"Simulation complete · No robot commands sent":"Block "+(run.index()+1)+" / "+blocks.size()+" · Simulated distance "+run.distanceCm()+" cm · Trackers "+run.trackerLeft()+" / "+run.trackerRight());if(!run.finished())main.postDelayed(this,16);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);UiUtils.configureStandardWindow(this);
        android.content.SharedPreferences prefs=getSharedPreferences("neobot_program_practice",0);blocks=NeobotProgram.decode(prefs.getString("blocks",""));customCode=prefs.getBoolean("custom",false);editing=prefs.getBoolean("editing",false);
        LinearLayout body=LearningWorkspaceUi.column(this);body.addView(LearningWorkspaceUi.text(this,"Programming practice",28));body.addView(LearningWorkspaceUi.text(this,"Arrange blocks, preview their behavior, then export C++ for the Arduino IDE. This simulation does not power or drive your robot.",15));
        LinearLayout toolbar=new LinearLayout(this);toolbar.addView(LearningWorkspaceUi.button(this,"Add block",this::add),new LinearLayout.LayoutParams(0,-2,1));toolbar.addView(LearningWorkspaceUi.button(this,"Blocks / C++",this::toggle),new LinearLayout.LayoutParams(0,-2,1));body.addView(toolbar);
        rows=new LinearLayout(this);rows.setOrientation(1);body.addView(rows);
        code=new EditText(this);code.setTypeface(Typeface.MONOSPACE);code.setTextSize(13);code.setGravity(Gravity.TOP);code.setMinLines(14);code.setSingleLine(false);code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);code.setHorizontallyScrolling(true);code.setContentDescription("Editable Arduino C++ sketch");body.addView(code);
        settingCode=true;code.setText(customCode?prefs.getString("code",NeobotProgram.cpp(blocks)):NeobotProgram.cpp(blocks));settingCode=false;
        code.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){if(!settingCode){customCode=true;stop();status.setText("Edited C++ · Export to compile in Arduino IDE. On-screen simulation runs blocks only.");}}public void afterTextChanged(Editable s){}});
        simulation=new SimulationView();body.addView(simulation,new LinearLayout.LayoutParams(-1,UiUtils.dp(this,250)));status=LearningWorkspaceUi.text(this,"Ready · Simulation uses the blocks above",14);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(status);
        LinearLayout actions=new LinearLayout(this);actions.addView(LearningWorkspaceUi.button(this,"Run blocks",this::simulate),new LinearLayout.LayoutParams(0,-2,1));actions.addView(LearningWorkspaceUi.button(this,"Stop",this::stop),new LinearLayout.LayoutParams(0,-2,1));actions.addView(LearningWorkspaceUi.button(this,"Export .ino",this::export),new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);
        body.addView(LearningWorkspaceUi.button(this,"Read programming lessons",()->startActivity(new Intent(this,LearningActivity.class))));body.addView(LearningWorkspaceUi.button(this,"Back",this::finish));setContentView(LearningWorkspaceUi.scroll(this,body));UiUtils.applyStandardInsets(this);
        voice=new AssemblyVoiceGuide(this,s->{});render();voice.speak("Programming practice. Add blocks to build a program. Run blocks previews a simulation only. You can edit and export the C plus plus sketch for the Arduino IDE.","practice:welcome");
    }
    private void render(){rows.removeAllViews();for(int i=0;i<blocks.size();i++){final int index=i;LinearLayout row=new LinearLayout(this);Button label=LearningWorkspaceUi.button(this,(i+1)+". "+blocks.get(i).label(),()->edit(index));row.addView(label,new LinearLayout.LayoutParams(0,-2,1));Button up=LearningWorkspaceUi.button(this,"↑",()->mutate(()->Collections.swap(blocks,index,index-1)));up.setContentDescription("Move block "+(i+1)+" up");up.setEnabled(i>0);row.addView(up,new LinearLayout.LayoutParams(UiUtils.dp(this,52),-2));Button remove=LearningWorkspaceUi.button(this,"×",()->mutate(()->blocks.remove(index)));remove.setContentDescription("Remove block "+(i+1));row.addView(remove,new LinearLayout.LayoutParams(UiUtils.dp(this,52),-2));rows.addView(row);}rows.setVisibility(editing?View.GONE:View.VISIBLE);code.setVisibility(editing?View.VISIBLE:View.GONE);}
    private void mutate(Runnable change){if(customCode){new AlertDialog.Builder(this).setTitle("Regenerate C++ from blocks?").setMessage("This block edit replaces your custom C++ draft. Export it first if you want to keep it.").setNegativeButton("Keep draft",null).setPositiveButton("Regenerate",(d,w)->{customCode=false;apply(change);}).show();}else apply(change);}
    private void apply(Runnable change){stop();change.run();settingCode=true;code.setText(NeobotProgram.cpp(blocks));settingCode=false;customCode=false;render();save();}
    private void add(){if(blocks.size()>=100){status.setText("This practice program supports up to 100 blocks.");return;}String[] names=Arrays.stream(NeobotProgram.Kind.values()).map(k->k.name().replace('_',' ')).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Choose a block").setItems(names,(d,w)->mutate(()->blocks.add(new NeobotProgram.Block(NeobotProgram.Kind.values()[w],160,1000)))).show();}
    private void edit(int index){NeobotProgram.Block b=blocks.get(index);LinearLayout body=PhysicalCheckUi.body(this);body.addView(LearningWorkspaceUi.text(this,"Duration (50–30000 ms)",15));EditText duration=new EditText(this);duration.setInputType(2);duration.setText(""+b.durationMs);body.addView(duration);body.addView(LearningWorkspaceUi.text(this,"Motor PWM (0–255)",15));EditText pwm=new EditText(this);pwm.setInputType(2);pwm.setText(""+b.pwm);body.addView(pwm);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(b.kind.name().replace('_',' ')).setView(body).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();dialog.setOnShowListener(d->{PhysicalCheckUi.style(dialog);dialog.getButton(-1).setOnClickListener(v->{try{NeobotProgram.Block replacement=new NeobotProgram.Block(b.kind,Integer.parseInt(pwm.getText().toString()),Integer.parseInt(duration.getText().toString()));dialog.dismiss();mutate(()->blocks.set(index,replacement));}catch(IllegalArgumentException invalid){duration.setError("Use duration 50–30000 and PWM 0–255");}});});dialog.show();}
    private void toggle(){editing=!editing;render();voice.speak(editing?"C plus plus sketch. Edits can be exported for the Arduino IDE.":"Block workspace. Tap a block to edit its duration and motor speed.","practice:mode:"+editing);}
    private void simulate(){stop();if(customCode){status.setText("Custom C++ is not simulated. Export it to compile; regenerate from blocks to use the simulation.");return;}if(blocks.isEmpty()){status.setText("Add a block first.");return;}run=new ProgramSimulator(blocks);tickTime=SystemClock.elapsedRealtime();main.post(tick);voice.speak("Running the block simulation. No commands are sent to your robot.","practice:run:"+tickTime);}
    private void stop(){main.removeCallbacks(tick);run=null;if(simulation!=null)simulation.invalidate();if(status!=null)status.setText("Simulation stopped · No robot commands sent");}
    private void export(){pendingExport=code.getText().toString();Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/x-c++src").putExtra(Intent.EXTRA_TITLE,"assembl_ar_neobot.ino");try{startActivityForResult(intent,7);}catch(ActivityNotFoundException missing){status.setText("No document provider is available for export.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=7||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String text=pendingExport==null?code.getText().toString():pendingExport;io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No output stream");out.write(text.getBytes(StandardCharsets.UTF_8));runOnUiThread(()->status.setText("Sketch exported · Open it in Arduino IDE to compile and upload."));}catch(IOException|SecurityException failure){runOnUiThread(()->status.setText("Export failed. Choose a writable destination and try again."));}});}
    private void save(){if(code!=null)getSharedPreferences("neobot_program_practice",0).edit().putString("blocks",NeobotProgram.encode(blocks)).putString("code",code.getText().toString()).putBoolean("custom",customCode).putBoolean("editing",editing).apply();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("pending_export",pendingExport);save();}
    @Override protected void onRestoreInstanceState(Bundle state){super.onRestoreInstanceState(state);pendingExport=state.getString("pending_export");}
    @Override protected void onPause(){stop();save();if(voice!=null)voice.stop();super.onPause();}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);if(voice!=null)voice.close();io.shutdown();super.onDestroy();}
    private final class SimulationView extends View {
        final Paint p=new Paint(3);SimulationView(){super(ProgrammingPracticeActivity.this);setContentDescription("Block program simulation on a 300 by 300 centimeter practice floor");}
        @Override protected void onDraw(Canvas c){super.onDraw(c);float size=Math.min(getWidth(),getHeight())-16,left=(getWidth()-size)/2,top=8;c.save();c.translate(left,top);c.scale(size/300,size/300);p.setColor(0xFFE0EADF);c.drawRect(0,0,300,300,p);p.setColor(0xFF677C6D);p.setStrokeWidth(2);c.drawLine(150,0,150,300,p);double x=run==null?150:run.x(),y=run==null?150:run.y(),angle=run==null?-90:Math.toDegrees(run.heading());c.save();c.translate((float)x,(float)y);c.rotate((float)angle+90);p.setColor(0xFF304F3C);c.drawRoundRect(-12,-16,12,16,3,3,p);p.setColor(run!=null&&run.led()?0xFFB2E34F:0xFF8CA394);c.drawCircle(0,-10,4,p);p.setColor(Color.BLACK);c.drawRect(-16,-10,-12,10,p);c.drawRect(12,-10,16,10,p);c.restore();c.restore();}
    }
}
